<template><div class="bm-glass grid gap-2 rounded-md p-3 sm:grid-cols-[1fr_220px_auto]"><input :value="search" class="bm-admin-input" placeholder="Buscar" @input="$emit('update:search', ($event.target as HTMLInputElement).value)"><select :value="status" class="bm-admin-input" @change="$emit('update:status', ($event.target as HTMLSelectElement).value)"><option value="">Todos os status</option><option v-for="item in statuses" :key="item" :value="item">{{ item }}</option></select><button class="bm-button-glass rounded-md px-4 text-xs font-black" type="button" @click="$emit('reload')">Filtrar</button></div></template>
<script setup lang="ts">defineProps<{ search: string, status: string, statuses: string[] }>(); defineEmits<{ 'update:search': [value: string], 'update:status': [value: string], reload: [] }>()</script>
